class Solution {
public:
    int longestBalancedSubarray(vector<int>& nums) {
        unordered_map<string, int> seen;
        seen["0,0"] = -1;
        int c0 = 0, c1 = 0, c2 = 0;
        int max_len = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int r = (nums[i] % 3 + 3) % 3;
            if (r == 0) c0++;
            else if (r == 1) c1++;
            else c2++;
            string key = to_string(c1 - c0) + "," + to_string(c2 - c0);
            if (seen.count(key)) {
