import java.util.*;

class Solution {
    public int longestBalancedSubarray(int[] nums) {
        Map<String, Integer> seen = new HashMap<>();
        seen.put("0,0", -1);
        int c0 = 0, c1 = 0, c2 = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            int r = (nums[i] % 3 + 3) % 3;
            if (r == 0) c0++;
            else if (r == 1) c1++;
            else c2++;
            String key = (c1 - c0) + "," + (c2 - c0);
            if (seen.containsKey(key)) {
                maxLen = Math.max(maxLen, i - seen.get(key));
            } else {
                seen.put(key, i);
            }
        }
        return maxLen;
    }
}

var longestBalancedSubarray = function(nums) {
    const seen = new Map();
    seen.set("0,0", -1);
    let c0 = 0, c1 = 0, c2 = 0;
    let maxLen = 0;
    for (let i = 0; i < nums.length; i++) {
        const r = ((nums[i] % 3) + 3) % 3;
        if (r === 0) c0++;
        else if (r === 1) c1++;
        else c2++;
        const key = `${c1 - c0},${c2 - c0}`;
        if (seen.has(key)) {
            maxLen = Math.max(maxLen, i - seen.get(key));
        } else {
            seen.set(key, i);
        }
    }
    return maxLen;
};
